tool_calls.arguments:
{"command": "cd /tmp && cat > patch.json <<'EOF'
{
  "spec": {
    "template": {
      "spec": {
        "containers": [
          {
            "name": "app",
            "livenessProbe": {
              "httpGet": {"path": "/", "port": 80, "scheme": "HTTP"},
              "initialDelaySeconds": 0,
              "periodSeconds": 10,
              "timeoutSeconds": 1,
              "successThreshold": 1,
              "failureThreshold": 3
            },
            "startupProbe": {
              "httpGet": {"path": "/", "port": 80, "scheme": "HTTP"},
              "initialDelaySeconds": 0,
              "periodSeconds": 2,
              "timeoutSeconds": 1,
              "successThreshold": 1,
              "failureThreshold": 15
            }
          }
        ]
      }
    }
  }
}
EOF
kubectl patch deployment app -n default --type=strategic -p "$(cat patch.json)" 2>&1"}

